"""Import and validation logic for the permit workflow."""

from __future__ import annotations

import csv
import datetime as dt
import json
import re
import sqlite3
import xml.etree.ElementTree as ET
from decimal import Decimal, InvalidOperation
from pathlib import Path
from typing import Iterable, Iterator, Mapping, Sequence


APPLICATION_FIELDS = (
    "source_id", "revision", "parcel_id", "owner_id", "permit_type",
    "submitted_date", "closed_date", "fee_paid",
)
DATE_PATTERN = re.compile(r"\d{4}-\d{2}-\d{2}\Z")
CURRENCY_PATTERN = re.compile(r"-?\d+\.\d{2}\Z")
INTEGER_PATTERN = re.compile(r"-?\d+\Z")
CENT = Decimal("0.01")

SCHEMA = """
PRAGMA foreign_keys = ON;
CREATE TABLE applications (
    application_id INTEGER PRIMARY KEY,
    source_id TEXT NOT NULL UNIQUE,
    revision TEXT NOT NULL,
    revision_number INTEGER,
    parcel_id TEXT NOT NULL,
    owner_id TEXT NOT NULL,
    permit_type TEXT NOT NULL,
    submitted_date TEXT NOT NULL,
    closed_date TEXT NOT NULL,
    fee_paid TEXT NOT NULL,
    fee_paid_value TEXT
);
CREATE TABLE application_parse_errors (
    application_id INTEGER NOT NULL REFERENCES applications(application_id),
    field_name TEXT NOT NULL,
    PRIMARY KEY (application_id, field_name)
);
CREATE TABLE parcels (
    parcel_id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, zone TEXT NOT NULL
);
CREATE TABLE owners (owner_id TEXT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE zoning_rules (
    zone TEXT NOT NULL, permit_type TEXT NOT NULL,
    PRIMARY KEY (zone, permit_type)
);
CREATE TABLE document_requirements (
    permit_type TEXT NOT NULL, document_type TEXT NOT NULL,
    PRIMARY KEY (permit_type, document_type)
);
CREATE TABLE fee_table (
    permit_type TEXT PRIMARY KEY, required_fee TEXT NOT NULL
);
CREATE TABLE attachments (
    document_id TEXT PRIMARY KEY,
    source_id TEXT NOT NULL,
    document_type TEXT NOT NULL,
    expires_on TEXT NOT NULL,
    filename TEXT NOT NULL
);
CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
"""


def _text(value: object) -> str:
    return "" if value is None else str(value)


def _parse_integer(value: str) -> int | None:
    if not INTEGER_PATTERN.fullmatch(value):
        return None
    try:
        return int(value)
    except ValueError:
        return None


def _valid_date(value: str) -> bool:
    if not DATE_PATTERN.fullmatch(value):
        return False
    try:
        dt.date.fromisoformat(value)
    except ValueError:
        return False
    return True


def _parse_currency(value: str) -> Decimal | None:
    if not CURRENCY_PATTERN.fullmatch(value):
        return None
    try:
        parsed = Decimal(value)
    except InvalidOperation:
        return None
    return parsed if parsed.is_finite() else None


def _normalize_application(record: Mapping[str, object]) -> dict[str, object]:
    normalized: dict[str, object] = {
        field: _text(record.get(field)) for field in APPLICATION_FIELDS
    }
    revision = _parse_integer(str(normalized["revision"]))
    paid = _parse_currency(str(normalized["fee_paid"]))
    errors: list[str] = []
    if revision is None:
        errors.append("revision")
    if not _valid_date(str(normalized["submitted_date"])):
        errors.append("submitted_date")
    closed_date = str(normalized["closed_date"])
    if closed_date and not _valid_date(closed_date):
        errors.append("closed_date")
    if paid is None:
        errors.append("fee_paid")
    normalized["revision_number"] = revision
    normalized["fee_paid_value"] = str(paid) if paid is not None else None
    normalized["parse_errors"] = errors
    return normalized


def _application_records(inputs: Path) -> Iterator[dict[str, object]]:
    with (inputs / "applications.json").open(encoding="utf-8") as handle:
        # parse_float retains lexical trailing zeroes needed by the currency format check.
        payload = json.load(handle, parse_float=Decimal)
    for record in payload["applications"]:
        yield _normalize_application(record)
    root = ET.parse(inputs / "applications.xml").getroot()
    for element in root.findall("application"):
        record = {child.tag: child.text or "" for child in element}
        yield _normalize_application(record)


def _current_applications(inputs: Path) -> list[dict[str, object]]:
    """Select current revisions while retaining first-seen ID order."""
    current: dict[str, dict[str, object]] = {}
    ordered_ids: list[str] = []
    for record in _application_records(inputs):
        source_id = str(record["source_id"])
        existing = current.get(source_id)
        if existing is None:
            ordered_ids.append(source_id)
            current[source_id] = record
            continue
        incoming_revision = record["revision_number"]
        existing_revision = existing["revision_number"]
        if (
            isinstance(incoming_revision, int)
            and isinstance(existing_revision, int)
            and incoming_revision > existing_revision
        ):
            current[source_id] = record
    return [current[source_id] for source_id in ordered_ids]


def _read_csv(path: Path) -> list[dict[str, str]]:
    with path.open(newline="", encoding="utf-8") as handle:
        return list(csv.DictReader(handle))


def _replace_database(database: Path) -> sqlite3.Connection:
    database.parent.mkdir(parents=True, exist_ok=True)
    connection = sqlite3.connect(database)
    objects = connection.execute(
        "SELECT type, name FROM sqlite_master "
        "WHERE name NOT LIKE 'sqlite_%' AND type IN ('table', 'view', 'trigger')"
    ).fetchall()
    connection.execute("PRAGMA foreign_keys = OFF")
    for object_type, name in objects:
        quoted = '"' + name.replace('"', '""') + '"'
        connection.execute(f"DROP {object_type.upper()} {quoted}")
    connection.executescript(SCHEMA)
    return connection


def _insert_csv(
    connection: sqlite3.Connection,
    table: str,
    columns: Sequence[str],
    rows: Iterable[Mapping[str, str]],
) -> None:
    placeholders = ", ".join("?" for _ in columns)
    column_sql = ", ".join(columns)
    connection.executemany(
        f"INSERT INTO {table} ({column_sql}) VALUES ({placeholders})",
        ([row[column] for column in columns] for row in rows),
    )


def import_data(inputs: Path, database: Path) -> None:
    """Import applications and validation reference data into SQLite."""
    applications = _current_applications(inputs)
    connection = _replace_database(database)
    try:
        with connection:
            for application_id, record in enumerate(applications, 1):
                connection.execute(
                    """INSERT INTO applications (
                           application_id, source_id, revision, revision_number,
                           parcel_id, owner_id, permit_type, submitted_date,
                           closed_date, fee_paid, fee_paid_value
                       ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                    (
                        application_id, record["source_id"], record["revision"],
                        record["revision_number"], record["parcel_id"],
                        record["owner_id"], record["permit_type"],
                        record["submitted_date"], record["closed_date"],
                        record["fee_paid"], record["fee_paid_value"],
                    ),
                )
                connection.executemany(
                    "INSERT INTO application_parse_errors VALUES (?, ?)",
                    ((application_id, field) for field in record["parse_errors"]),
                )
            _insert_csv(connection, "parcels", ("parcel_id", "owner_id", "zone"),
                        _read_csv(inputs / "parcels.csv"))
            _insert_csv(connection, "owners", ("owner_id", "name"),
                        _read_csv(inputs / "owners.csv"))
            _insert_csv(connection, "zoning_rules", ("zone", "permit_type"),
                        _read_csv(inputs / "zoning_rules.csv"))
            _insert_csv(connection, "document_requirements",
                        ("permit_type", "document_type"),
                        _read_csv(inputs / "document_requirements.csv"))
            fee_rows = _read_csv(inputs / "fee_table.csv")
            for row in fee_rows:
                row["required_fee"] = str(Decimal(row["required_fee"]))
            _insert_csv(connection, "fee_table", ("permit_type", "required_fee"), fee_rows)
            _insert_csv(connection, "attachments",
                        ("document_id", "source_id", "document_type", "expires_on", "filename"),
                        _read_csv(inputs / "attachments.csv"))
            with (inputs / "settings.json").open(encoding="utf-8") as handle:
                settings = json.load(handle)
            connection.executemany(
                "INSERT INTO settings (key, value) VALUES (?, ?)",
                ((str(key), _text(value)) for key, value in settings.items()),
            )
    finally:
        connection.close()


def _money(value: Decimal) -> str:
    return format(value.quantize(CENT), ".2f")


def _write_csv(path: Path, header: Sequence[str], rows: Iterable[Sequence[object]]) -> None:
    with path.open("w", encoding="utf-8", newline="") as handle:
        writer = csv.writer(handle, lineterminator="\n")
        writer.writerow(header)
        writer.writerows(rows)


def validate_data(database: Path, output: Path) -> None:
    """Validate current applications and replace the three CSV reports."""
    connection = sqlite3.connect(database)
    connection.row_factory = sqlite3.Row
    try:
        applications = connection.execute(
            "SELECT * FROM applications ORDER BY application_id"
        ).fetchall()
        parcels = {row["parcel_id"]: row for row in connection.execute("SELECT * FROM parcels")}
        owners = {row["owner_id"] for row in connection.execute("SELECT owner_id FROM owners")}
        zoning = {
            (row["zone"], row["permit_type"])
            for row in connection.execute("SELECT zone, permit_type FROM zoning_rules")
        }
        requirements: dict[str, set[str]] = {}
        for row in connection.execute(
            "SELECT permit_type, document_type FROM document_requirements"
        ):
            requirements.setdefault(row["permit_type"], set()).add(row["document_type"])
        fee_table = {
            row["permit_type"]: Decimal(row["required_fee"])
            for row in connection.execute("SELECT permit_type, required_fee FROM fee_table")
        }
        attachments: dict[str, dict[str, list[str]]] = {}
        for row in connection.execute(
            "SELECT source_id, document_type, expires_on FROM attachments"
        ):
            attachments.setdefault(row["source_id"], {}).setdefault(
                row["document_type"], []
            ).append(row["expires_on"])
        validation_date = dt.date.fromisoformat(
            connection.execute(
                "SELECT value FROM settings WHERE key = 'validation_date'"
            ).fetchone()[0]
        )
        parse_errors: dict[int, list[str]] = {}
        for row in connection.execute(
            "SELECT application_id, field_name FROM application_parse_errors"
        ):
            parse_errors.setdefault(row["application_id"], []).append(row["field_name"])
    finally:
        connection.close()

    application_rows: list[tuple[object, ...]] = []
    issue_rows: list[tuple[object, ...]] = []
    fee_rows: list[tuple[object, ...]] = []
    for app in applications:
        application_id = app["application_id"]
        source_id = app["source_id"]
        application_rows.append(tuple(app[column] for column in (
            "application_id", "source_id", "revision", "parcel_id", "owner_id",
            "permit_type", "submitted_date", "closed_date",
        )))
        issues: list[tuple[str, str]] = [
            ("PARSE_ERROR", field) for field in parse_errors.get(application_id, [])
        ]

        parcel_id = app["parcel_id"]
        parcel = parcels.get(parcel_id) if parcel_id else None
        if parcel_id and parcel is None:
            issues.append(("PARCEL_NOT_FOUND", parcel_id))
        elif parcel is not None:
            owner_id = app["owner_id"]
            if owner_id not in owners or owner_id != parcel["owner_id"]:
                issues.append(("OWNER_MISMATCH", owner_id))
            pair = (parcel["zone"], app["permit_type"])
            if pair not in zoning:
                issues.append(("ZONING_INCOMPATIBLE", "/".join(pair)))

        app_attachments = attachments.get(source_id, {})
        for document_type in requirements.get(app["permit_type"], set()):
            expiries = app_attachments.get(document_type, [])
            if not expiries:
                issues.append(("MISSING_DOCUMENT", document_type))
            elif all(expiry and dt.date.fromisoformat(expiry) < validation_date for expiry in expiries):
                issues.append(("EXPIRED_DOCUMENT", document_type))

        required = fee_table.get(app["permit_type"])
        paid = Decimal(app["fee_paid_value"]) if app["fee_paid_value"] is not None else None
        if required is not None and paid is not None:
            if paid != required:
                issues.append(("FEE_MISMATCH",
                               f"required {_money(required)}; paid {_money(paid)}"))
            due = max(required - paid, Decimal("0.00"))
            fee_rows.append(
                (application_id, source_id, _money(required), _money(paid), _money(due))
            )
        else:
            fee_rows.append((
                application_id, source_id,
                _money(required) if required is not None else "",
                _money(paid) if paid is not None else "", "",
            ))
        issue_rows.extend(
            (application_id, source_id, code, detail)
            for code, detail in sorted(issues)
        )

    output.mkdir(parents=True, exist_ok=True)
    _write_csv(output / "applications.csv",
               ("application_id", "source_id", "revision", "parcel_id", "owner_id",
                "permit_type", "submitted_date", "closed_date"), application_rows)
    _write_csv(output / "validation_issues.csv",
               ("application_id", "source_id", "code", "detail"), issue_rows)
    _write_csv(output / "fees.csv",
               ("application_id", "source_id", "required_fee", "paid_fee", "fee_due"),
               fee_rows)
"""Command-line entry point for permitflow."""

from __future__ import annotations

import argparse
from pathlib import Path

from .workflow import import_data, validate_data


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="permitflow", description="Import and validate county permit records."
    )
    commands = parser.add_subparsers(dest="command", required=True)

    import_parser = commands.add_parser("import", help="import intake files into SQLite")
    import_parser.add_argument("inputs", type=Path, help="input directory")
    import_parser.add_argument("database", type=Path, help="SQLite database path")

    validate_parser = commands.add_parser("validate", help="validate imported records")
    validate_parser.add_argument("database", type=Path, help="SQLite database path")
    validate_parser.add_argument(
        "--output", type=Path, required=True, help="report output directory"
    )
    return parser


def main(argv: list[str] | None = None) -> int:
    args = build_parser().parse_args(argv)
    if args.command == "import":
        import_data(args.inputs, args.database)
    elif args.command == "validate":
        validate_data(args.database, args.output)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
